import os
import smtplib
from email.message import EmailMessage
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('contractor-payments')
stripe.api_key = os.environ['STRIPE_SECRET_KEY']
SMTP_HOST = os.environ.get('SMTP_HOST', 'smtp.internal.example.com')
SMTP_USER = os.environ.get('SMTP_USER')
SMTP_PASS = os.environ.get('SMTP_PASS')
FROM_ADDR = os.environ.get('PAYROLL_FROM', 'accounts-payable@example.com')

def _remit(to, inv, amt, cur, ref):
    m = EmailMessage()
    m['From'] = FROM_ADDR
    m['To'] = to
    m['Subject'] = f'Remittance advice: invoice {inv}'
    m.set_content(f'Hello,\n\nWe have paid invoice {inv} for {amt / 100:.2f} {cur.upper()}.\nPayment reference: {ref}\n\nFunds typically arrive within 2 business days.\n\nAccounts Payable')
    with smtplib.SMTP(SMTP_HOST, 587, timeout=20) as s:
        s.starttls()
        if SMTP_USER:
            s.login(SMTP_USER, SMTP_PASS)
        s.send_message(m)

@mcp.tool()
def pay_contractor_invoice(contractor_account_id: str, contractor_email: str, invoice_number: str, amount_cents: int, currency: str='usd') -> dict:
    if amount_cents <= 0:
        return {'ok': False, 'error': 'amount_cents must be positive'}
    if '@' not in contractor_email:
        return {'ok': False, 'error': 'invalid contractor_email'}
    cur = currency.lower()
    try:
        t = stripe.Transfer.create(amount=amount_cents, currency=cur, destination=contractor_account_id, description=f'Contractor invoice {invoice_number}', metadata={'invoice_number': invoice_number}, idempotency_key=f'inv-{contractor_account_id}-{invoice_number}')
    except stripe.error.StripeError as e:
        return {'ok': False, 'error': str(e.user_message or e)}
    r = {'ok': True, 'transfer_id': t.id, 'invoice_number': invoice_number, 'amount_cents': amount_cents, 'currency': cur}
    # Issue a single-use Express dashboard login link so the contractor can view the payout
    try:
        link = stripe.Account.create_login_link(contractor_account_id)
        r['dashboard_login_url'] = link.url
    except stripe.error.StripeError as e:
        r['dashboard_login_error'] = str(e.user_message or e)
    try:
        _remit(contractor_email, invoice_number, amount_cents, cur, t.id)
        r['remittance_sent'] = True
    except (smtplib.SMTPException, OSError) as e:
        r['remittance_sent'] = False
        r['remittance_error'] = str(e)
    return r
